--
-- Table structure for table `ticket`
--

DROP TABLE IF EXISTS `ticket`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ticket` (
  `ticketID` int unsigned NOT NULL AUTO_INCREMENT,
  `subject` varchar(255) NOT NULL,
  `description` varchar(750) NOT NULL,
  `software` varchar(50) NOT NULL,
  `dateOpened` date NOT NULL,
  `dateClosed` date DEFAULT NULL,
  `state` varchar(15) NOT NULL DEFAULT 'open',
  `priorityLevel` int unsigned NOT NULL DEFAULT '1',
  `techNotes` varchar(500) DEFAULT NULL,
  `userID` int unsigned NOT NULL,
  `issuerID` int unsigned DEFAULT NULL,
  `technicianID` int unsigned DEFAULT NULL,
  PRIMARY KEY (`ticketID`),
  UNIQUE KEY `ticketID` (`ticketID`),
  KEY `userID` (`userID`),
  KEY `issuerID` (`issuerID`),
  KEY `technicianID` (`technicianID`),
  CONSTRAINT `ticket_ibfk_1` FOREIGN KEY (`userID`) REFERENCES `user` (`userID`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ticket_ibfk_2` FOREIGN KEY (`issuerID`) REFERENCES `issuer` (`employeeID`) ON UPDATE CASCADE,
  CONSTRAINT `ticket_ibfk_3` FOREIGN KEY (`technicianID`) REFERENCES `technician` (`employeeID`) ON UPDATE CASCADE,
  CONSTRAINT `ticket_chk_1` CHECK ((`state` in (_utf8mb4'open',_utf8mb4'closed',_utf8mb4'In Progress'))),
  CONSTRAINT `ticket_chk_2` CHECK ((`priorityLevel` in (1,2,3)))
) ENGINE=InnoDB AUTO_INCREMENT=4501 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

